import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomTextArea,
  FileUploader,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import makeAnimated from "react-select/animated";
import { ToastContainer, toast } from "react-toastify";
import restaurantApi from "../../../api/restaurants/restaurantApi";
import {
  createMenuItem,
  resetRedux,
  updateMenuItem,
} from "../../../redux/restaurants/menuitems/actions";
import { useDispatch, useSelector } from "react-redux";
import { Modal } from "antd";

export default function MenuItemFormModal({
  ismodalOpen,
  setisModalOpen,
  menuItemToEdit,
  modalTitle = "Add new menu item",
  updated,
  setUpdated,
}) {
  // const { isOpen, onOpen, onOpenChange } = useDisclosure();
  const animatedComponent = makeAnimated();
  const [menuItem, setMenuItem] = useState(
    menuItemToEdit ? menuItemToEdit : null
  );
  const dispatch = useDispatch();
  const loading = useSelector((state) => state.MenuItems.menu_item);
  const menu_item = useSelector((state) => state.MenuItems.loading);
  const errors = useSelector((state) => state.MenuItems.errors);
  const success = useSelector((state) => state.MenuItems.success);

  const [menus, setMenus] = useState([]);
  const getUserBranchMenusActionsApi = useApi(restaurantApi.restaurantAction);
  const restaurantActionsApi = useApi(restaurantApi.restaurantAction);
  const getUserBranchMenus = async () => {
    await getUserBranchMenusActionsApi.request({
      action: "GetBranchMenus",
    });
  };

  useEffect(() => {
    getUserBranchMenus();
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  useEffect(() => {
    if (
      getUserBranchMenusActionsApi.data &&
      getUserBranchMenusActionsApi.data.length
    ) {
      setMenus(
        getUserBranchMenusActionsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    console.log("getRoutesActionsApi.data", getUserBranchMenusActionsApi.data);
  }, [getUserBranchMenusActionsApi.data]);

  useEffect(() => {
    dispatch(resetRedux());
  }, []);

  useEffect(() => {
    if (success) {
      setisModalOpen(false);
      setUpdated(true);
    }
  }, [success]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  const formik = useFormik({
    initialValues: {
      menu: menuItem
        ? { label: menuItem.menu_title, value: menuItem.menu }
        : "",
      title: menuItem ? menuItem.title : "",
      price: menuItem ? menuItem.price : 0.0,
      description: menuItem ? menuItem.description : "",
    },

    validationSchema: Yup.object({
      menu: Yup.object().required("Menu is required"),
      title: Yup.string().required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      //Generate form data to automatically encode data for upload using axios
      let data = new FormData();
      data.append("title", values.title);
      data.append("menu", values.menu.value);
      data.append("description", values.description);

      if (values.images && values.images.length) {
        values.images.map((x) => {
          data.append("images", x);
        });
      }

      if (menuItemToEdit) {
        dispatch(updateMenuItem(data, menuItemToEdit.id));
      } else {
        dispatch(createMenuItem(data));
      }

      // if (item) {

      //     handleMenuAction({
      //         "action": "UpdateBranchMenuItem",
      //         "menu_item_details": {
      //             "menu_item": menu_item.id,
      //             "title": values.title,
      //             "price": values.price,
      //             "menu": values.menu.value,
      //             "description": values.description ? values.description : '',
      //         }
      //     })
      // } else {
      //     handleMenuAction({
      //         "action": "CreateBranchMenuItem",
      //         "menu_item_details": {
      //             "title": values.title,
      //             "price": values.price,
      //             "menu": values.menu.value,
      //             "description": values.description ? values.description : '',
      //         }
      //     })
      // }

      // resetForm();
    },
  });

  const handleRemoveSelectedImage = (file) => {
    console.log("file", file);
    // formik.values.images.filter((x) => x.preview !== file.preview);

    formik.setFieldValue(
      "images",
      formik.values.images.filter((x) => x.preview !== file.preview)
    );
  };

  return (
    <div className="w-full">
      <Modal
        width={500}
        className="w-full text-center"
        title={menuItemToEdit ? `EDIT ${menuItemToEdit.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <div className="w-full grid grid-cols-1 mt-5 gap-1 ">
            <CustomFormItem
              touched={formik.touched.title}
              error={formik.errors.title}
            >
              <CustomInput
                required={true}
                label="Enter title"
                id="title"
                name="title"
                onChange={formik.handleChange}
                placeholder="Enter menu item title"
                size="large"
                type="text"
                value={formik.values.title}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.menu}
              error={formik.errors.menu}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="menu"
                id="menu"
                label="Select menu"
                size="large"
                onChange={(value) => formik.setFieldValue("menu", value)}
                value={formik.values.county}
                placeholder="Select menu"
                options={menus}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.description}
              error={formik.errors.description}
            >
              <CustomTextArea
                required={true}
                label="Type short description"
                id="description"
                name="description"
                onChange={formik.handleChange}
                placeholder="Enter description"
                size="large"
                type="text"
                value={formik.values.description}
              />
            </CustomFormItem>

            <CustomFormItem>
              <div className="bg-white w-full hover:cursor-pointer hover:bg-green-50">
                <FileUploader
                  placeholder="Upload menu item image"
                  formik={formik}
                  name="images"
                  types=".png,.jpg,.jpeg"
                  value={formik.values.images}
                  accept={{
                    "image/png": [".png"],
                    "image/jpeg": [".jpeg"],
                  }}
                />
                {formik.values.images && formik.values.images.length > 0 && (
                  <div className="shadow-md rounded my-5 bg-zinc-100 p-5">
                    <h2 className="text-center font-bold mb-5">
                      Images selected for upload
                    </h2>
                    <div className="container flex flex-wrap mx-auto">
                      <div className="grid grid-cols-4 gap-2 sm:grid-cols-4 gap-3">
                        {formik.values.images?.map((file) => (
                          <div
                            className="md:shrink-0 rounded "
                            key={file.preview}
                          >
                            <button
                              onClick={() => handleRemoveSelectedImage(file)}
                              className="flex  absolute text-red-800 border-red-800 border"
                            >
                              x
                            </button>
                            <img
                              className="h-10 w-full object-cover md:h-full md:w-48 shadow-md"
                              src={file.preview}
                              alt=""
                            />
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </CustomFormItem>
          </div>
          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
